            }
        }

        let tail = N - 2;
        let mut raw = [0u64; 4];
        for index in tail..N {
            let offset = (slot * N + index) * 4;
            let value = u32::from_le_bytes(bytes[offset..offset + 4].try_into().ok()?);
            invalid |= u32::from(value >= P);
            let value = u64::from(value & P);
