            c1: CM31::ZERO,
        };
        let u = QM31 {
            c0: CM31::ZERO,
            c1: CM31::ONE,
        };
        let basis = [QM31::ONE, i, u, i.mul(u)];
        let mut state = 0x6c8e_9cf5_7093_2bd1u64;
