                assert_eq!(qm31_pack_base4(&values[..len]), expected, "len={len}");
            }
        }

        let edge = QM31 {
            c0: CM31::new(M31(P - 1), M31(P - 1)),
            c1: CM31::new(M31(P - 1), M31(P - 1)),
        };
        let expected = basis
            .iter()
            .fold(QM31::ZERO, |sum, basis| sum.add(edge.mul(*basis)));
