        wrong_context.layout_factor_fingerprint ^= 1;
        assert_eq!(
            begin_state_only_hiding_precommit(&mut wrong_factor, wrong_context),
            Err(StateOnlyHidingScheduleError::LayoutFactorFingerprint)
        );
    }

